entries[447328] = { ["name"] = "Lapidary's Bismuth Clamps", ["text"] = "2 sec cast 2\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nExtravagant Emerald , Handful of Bismuth Bolts (8), Whimsical Wiring (2), Gyrating Gear (2)\nOptional Reagents:\nDiscovery:\nComprehensibly Organized Ideas\n\nLapidary's Bismuth Clamps\nBinds when equipped\nJewelcrafting Tool\n+ 132 Random Stat 1\nEquip: +8 Khaz Algar Jewelcrafting Skill\n68\n\"Provides all the necessary tools for jewelcrafting in one convenient package.\"" }
