entries[447340] = { ["name"] = "Chaos Circuit", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nNull Stone , Aqirite (5), Ironclaw Ore (3)\nOptional Reagents:\nDiscovery:\nScour Through Scrap\n\nCrafting Reagent\n\nProvides the following property: Chaos Circuit\n\"Crafted by Khaz Algar Engineers for use in their inventions. Can be bought and sold on the Auction House.\"" }
entries[447341] = { ["name"] = "Entropy Enhancer", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nWrithing Sample , Bismuth (4), Aqirite (2), Ironclaw Ore (2)\nOptional Reagents:\nDiscovery:\nScour Through Scrap\n\nCrafting Reagent\n\nProvides the following property: Entropy Enhancer\n\"Crafted by Khaz Algar Engineers for use in their inventions. Can be bought and sold on the Auction House.\"" }
entries[447342] = { ["name"] = "Potion Bomb of Speed", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (10), Potion of the Reborn Cheetah (3), Handful of Bismuth Bolts (2), Whimsical Wiring (2), Gyrating Gear , Safety Switch\nOptional Reagents:\nDiscovery:\nInventing, Prototyping, and Notes\n\nUse: Throw a potion bomb which splashes up to 5 allies caught in the blast with a burst of 10-15% movement speed (based on crafting quality) for 20 sec.\n\nEnemies caught in the blast suffer 32 fire damage, split between them.\n68" }
entries[447343] = { ["name"] = "Potion Bomb of Recovery", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (10), Cavedweller's Delight (3), Handful of Bismuth Bolts (2), Whimsical Wiring (2), Gyrating Gear , Safety Switch\nOptional Reagents:\nDiscovery:\nInventing, Prototyping, and Notes\n\nUse: Throw a potion bomb which splashes up to 5 allies caught in the blast with a potion that increases healing received by 5-10% (based on crafting quality) for 12 sec.\n\nEnemies caught in the blast suffer 32 fire damage, split between them.\n68" }
entries[447344] = { ["name"] = "Potion Bomb of Power", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (10), Tempered Potion (3), Handful of Bismuth Bolts (2), Whimsical Wiring (2), Gyrating Gear , Safety Switch\nOptional Reagents:\nDiscovery:\nInventing, Prototyping, and Notes\n\nUse: Throw a potion bomb which splashes up to 5 allies caught in the blast with a potion that increases their primary stat by ( 17 / 5) for 30 sec.\n\nEnemies caught in the blast suffer 32 fire damage, split between them.\n68" }
entries[447350] = { ["name"] = "Tinker: Earthen Delivery Drill", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (25), Handful of Bismuth Bolts (24), Whimsical Wiring (12), Gyrating Gear (3), Chaos Circuit (3), Entropy Enhancer (2)\nOptional Reagents:\nDiscovery:\nInventing, Prototyping, and Notes\n\nTinker: Earthen Delivery Drill\nTinker Module\nUnique-Equipped: Earthen Delivery Drill (1)\nEarthen Delivery Drill\n\nEquip: Insert into a Tinker Socket for the following effect:\n\nEarthen Delivery Drill\nSummon an Earthen Delivery Drill to dig for an assortment of battleground buffs.\n\nThe drill lasts for 28 sec and can only be summoned while in combat. Can only be used in unrated battlegrounds and in War Mode on Khaz Algar.\n68\n\"Tinker quality and engineering specialization impact success chance. This warranty only applies to Algari equipment.\"" }
entries[447351] = { ["name"] = "Tinker: Heartseeking Health Injector", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (25), Algari Healing Potion (600), Handful of Bismuth Bolts (24), Whimsical Wiring (12), Gyrating Gear (3), Entropy Enhancer (4)\nOptional Reagents:\nDiscovery:\nInventing, Prototyping, and Notes\n\nTinker: Heartseeking Health Injector\nTinker Module\nUnique-Equipped: Heartseeking Health Injector (1)\nHeartseeking Health Injector\n\nEquip: Insert into a Tinker Socket for the following effect:\n\nHeartseeking Health Injector\nInject a medicinal frostfire formula into your veins, instantly healing you for up to 32012 from a jolt of frost. To prevent sudden hypothermia, you will then burn for 30% of the amount healed.\n\nShares a cooldown with healing potions.\n68\n\"Tinker quality and engineering specialization impact success chance. With proper precautions, this tinker cannot malfunction. This warranty only applies to Algari equipment.\"" }
entries[447352] = { ["name"] = "P.0.W. x2", ["text"] = "2 sec cast 3\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nHandful of Bismuth Bolts (64), Whimsical Wiring (18), Gyrating Gear (12), Safety Switch (4), Chaos Circuit (2), Spark (#256) (2)\nOptional Reagents:\nSpecialization:\nEngineered Equipment - Guns\n\nP.0.W. x2\nBinds when picked up\nRanged Gun\n3,365 - 6,251 Damage Speed 3.00\n(1,603 damage per second)\n+2,129 Agility\n+9,748 Stamina\n+ 728 Random Stat 1\n+ 728 Random Stat 2\nDurability 120 / 120\n58\n\"Come on, shoot faster!\"" }
entries[447353] = { ["name"] = "Serrated Cogwheel", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nRadiant Ruby , Handful of Bismuth Bolts , Gyrating Gear , Entropy Enhancer\nOptional Reagents:\nSpecialization:\nInventing - Serrated Cogwheel\n\nSerrated Cogwheel\nOptional Crafting Reagent\n+25 Recipe Difficulty\nProvides the following property: Allocate the secondary stat of Engineering crafted goggles or bracers to Critical Strike.\nUsable with: Goggles and Bracers crafted with Khaz Algar Engineering.\n\"Can be bought and sold on the Auction House.\"" }
entries[447354] = { ["name"] = "Overclocked Cogwheel", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nExtravagant Emerald , Handful of Bismuth Bolts , Gyrating Gear , Entropy Enhancer\nOptional Reagents:\nSpecialization:\nInventing - Overclocked Cogwheel\n\nOverclocked Cogwheel\nOptional Crafting Reagent\n+25 Recipe Difficulty\nProvides the following property: Allocate the secondary stat of Engineering crafted goggles or bracers to Haste.\nUsable with: Goggles and Bracers crafted with Khaz Algar Engineering.\n\"Can be bought and sold on the Auction House.\"" }
entries[447355] = { ["name"] = "Impeccable Cogwheel", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nOstentatious Onyx , Handful of Bismuth Bolts , Gyrating Gear , Entropy Enhancer\nOptional Reagents:\nSpecialization:\nInventing - Impeccable Cogwheel\n\nImpeccable Cogwheel\nOptional Crafting Reagent\n+25 Recipe Difficulty\nProvides the following property: Allocate the secondary stat of Engineering crafted goggles or bracers to Mastery.\nUsable with: Goggles and Bracers crafted with Khaz Algar Engineering.\n\"Can be bought and sold on the Auction House.\"" }
entries[447356] = { ["name"] = "Adjustable Cogwheel", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nStunning Sapphire , Handful of Bismuth Bolts , Gyrating Gear , Entropy Enhancer\nOptional Reagents:\nSpecialization:\nInventing - Adjustable Cogwheel\n\nAdjustable Cogwheel\nOptional Crafting Reagent\n+25 Recipe Difficulty\nProvides the following property: Allocate the secondary stat of Engineering crafted goggles or bracers to Versatility.\nUsable with: Goggles and Bracers crafted with Khaz Algar Engineering.\n\"Can be bought and sold on the Auction House.\"" }
entries[447357] = { ["name"] = "Recalibrated Safety Switch", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (15), Handful of Bismuth Bolts (8), Whimsical Wiring (2), Gyrating Gear (2), Safety Switch (4)\nOptional Reagents:\nDiscovery:\nComprehensibly Organized Ideas\n\nRecalibrated Safety Switch\nOptional Crafting Reagent\n+25 Recipe Difficulty\nProvides the following property: Reduces the likelihood of this device's tinker malfunctioning by 15%. Does not stack with similar specialization bonuses.\nUsable with: Goggles and Bracers crafted with Khaz Algar Engineering.\n\"Can be bought and sold on the Auction House.\"" }
entries[447360] = { ["name"] = "Complicated Fuse Box", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (15), Handful of Bismuth Bolts (6), Whimsical Wiring (2), Gyrating Gear (2), Chaos Circuit , Entropy Enhancer\nOptional Reagents:\nDiscovery:\nComprehensibly Organized Ideas\n\nComplicated Fuse Box\nOptional Crafting Reagent\n+25 Recipe Difficulty\nProvides the following property: When the tinker slotted within this device malfunctions, a fuse is flipped to prevent a hazardous outcome.\nUsable with: Goggles and Bracers crafted with Khaz Algar Engineering.\n\"Can be bought and sold on the Auction House.\"" }
entries[447364] = { ["name"] = "Irresistible Red Button", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (10), Handful of Bismuth Bolts (12), Whimsical Wiring (3), Gyrating Gear (4), Entropy Enhancer\nOptional Reagents:\nDiscovery:\nInventing, Prototyping, and Notes\n\nIrresistible Red Button\nBinds when picked up\nUse: Deploy a device that can be activated by you or a party or raid member when a crisis is imminent. When activated, it will attempt to resurrect all nearby allies at the end of combat.\n\nLasts for 1 hour or until activation. Must be deployed prior to combat.\n68\nRequires Khaz Algar Engineering\n(1)" }
entries[447365] = { ["name"] = "Pausing Pylon", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (10), Handful of Bismuth Bolts (8), Whimsical Wiring (2), Gyrating Gear (2)\nDiscovery:\nInventing, Prototyping, and Notes\n\nUse: Deploy a Pausing Pylon that will disrupt the natural metabolic processes of players standing nearby, halting the expiration of Khaz Algar Flasks, Phials, and Well Fed effects.\n\nThe pylon is extremely fragile and will detonate in the presence of violence.\n68" }
entries[447367] = { ["name"] = "Algari Repair Bot 11O", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (10), Handful of Bismuth Bolts (8), Whimsical Wiring , Gyrating Gear (2), Entropy Enhancer\nDiscovery:\nInventing, Prototyping, and Notes\n\nAlgari Repair Bot 11O\nBinds when picked up\nUse: Deploy a small earthen golem to allow you and fellow adventurers to repair your equipment.\n\nLasts for 10 min.\n68\nRequires Khaz Algar Engineering\n(1)" }
entries[447368] = { ["name"] = "Portable Profession Possibility Projector", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (10), Handful of Bismuth Bolts (12), Whimsical Wiring , Gyrating Gear (2), Entropy Enhancer\nDiscovery:\nInventing, Prototyping, and Notes\n\nPortable Profession Possibility Projector\nUse: Summon a Possibility Projector configured to satisfy the needs of crafting tables. Only one workbench can be displayed at a time and can only be changed by the Engineer. (10 Min Cooldown)\n68\nRequires Khaz Algar Engineering\n(1)" }
entries[447369] = { ["name"] = "Barrel of Fireworks", ["text"] = "2 sec cast 2\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (50), Handful of Bismuth Bolts (50), Whimsical Wiring (24), Gyrating Gear (10), Chaos Circuit (8), Entropy Enhancer (3)\nDiscovery:\nInventing, Prototyping, and Notes\n\nBarrel of Fireworks\nToy\nUse: Deploy a dangerous barrel of fireworks for 5 min so you and your friends can violently illuminate the night sky!\n\nOther players can opt-in to seeing the fireworks by attacking the barrel.\n\nCooldown reduced during drunken goblin revelries. (1 Hour Cooldown)" }
entries[447370] = { ["name"] = "Defective Escape Pod", ["text"] = "2 sec cast 2\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (50), Handful of Bismuth Bolts (75), Whimsical Wiring (10), Gyrating Gear (16), Safety Switch (6), Entropy Enhancer (2)\nDiscovery:\nInventing, Prototyping, and Notes\n\nDefective Escape Pod\nToy\nUse: Urgently seek shelter inside a defective escape pod. You won't get very far, but at least you are safe. (10 Min Cooldown)" }
entries[447371] = { ["name"] = "Filmless Camera", ["text"] = "2 sec cast 2\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (50), Handful of Bismuth Bolts (100), Whimsical Wiring (6), Gyrating Gear (8), Safety Switch , Entropy Enhancer\nDiscovery:\nInventing, Prototyping, and Notes\n\nFilmless Camera\nToy\nUse: Embrace your inner photographer! (30 Sec Cooldown)" }
entries[447372] = { ["name"] = "Wormhole Generator: Khaz Algar", ["text"] = "2 sec cast 2\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (50), Handful of Bismuth Bolts (125), Whimsical Wiring (8), Gyrating Gear (16), Chaos Circuit (4), Entropy Enhancer (4)\nDiscovery:\nInventing, Prototyping, and Notes\n\nWormhole Generator: Khaz Algar\nToy\nUse: Open a wormhole that allows the user to quickly travel to a random location in Khaz Algar. (30 Min Cooldown)\n68\nRequires Khaz Algar Engineering\n(1)" }
entries[447373] = { ["name"] = "Crowd Pummeler 2-30", ["text"] = "2 sec cast 3\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nBountiful Bolts (1000), Assorted Whirligigs (200), Blinker Fluid (80), Cataclysmic Converter (50), Pummel-Proof Plating (20), Pummel Permit\nThe required components can be purchased from Paxton Bombshell at Opportunity Point.\n\nYou may sometimes find these parts when you Pilfer Through Parts .\nDiscovery:\nComprehensibly Organized Ideas\n\nCrowd Pummeler 2-30\nMount (Account-wide)\nUse: Teaches you how to summon the Crowd Pummeler 2-30.\nSummons and dismisses this mount.\n1 to 80 ( 80)\nRequires\n\"Guaranteed to knock the teeth out from your enemies with a single punch!\"\nProfession:\nKhaz Algar Engineering" }
entries[447375] = { ["name"] = "Acolyte's Goggles", ["text"] = "2 sec cast 2\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (5), Handful of Bismuth Bolts (4), Whimsical Wiring , Gyrating Gear\nOptional Reagents:\nProfession Trainer:\nKhaz Algar Engineering (25)\nCost:\n125\n\nAcolyte's Goggles\nBinds when equipped\nHead Cloth\n396 Armor\n+634 Intellect\n+2,323 Stamina\n+ 888 Random Stat 1\n\nTinker Socket\n\nDurability 85 / 85\n58\nRequires Khaz Algar Engineering\n(1)" }
