entries[447377] = { ["name"] = "Tracker's Goggles", ["text"] = "2 sec cast 2\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (5), Handful of Bismuth Bolts (4), Whimsical Wiring , Gyrating Gear\nOptional Reagents:\nProfession Trainer:\nKhaz Algar Engineering (25)\nCost:\n125\n\nTracker's Goggles\nBinds when equipped\nHead Mail\n1004 Armor\n+634 [Agility or Intellect]+2,323 Stamina\n+ 888 Random Stat 1\n\nTinker Socket\n\nDurability 85 / 85\n58\nRequires Khaz Algar Engineering\n(1)" }
entries[447378] = { ["name"] = "Dredger's Goggles", ["text"] = "2 sec cast 2\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (5), Handful of Bismuth Bolts (4), Whimsical Wiring , Gyrating Gear\nOptional Reagents:\nProfession Trainer:\nKhaz Algar Engineering (25)\nCost:\n125\n\nDredger's Goggles\nBinds when equipped\nHead Plate\n1510 Armor\n+634 [Strength or Intellect]+2,323 Stamina\n+ 888 Random Stat 1\n\nTinker Socket\n\nDurability 85 / 85\n58\nRequires Khaz Algar Engineering\n(1)" }
entries[447379] = { ["name"] = "4UT0-41M3R", ["text"] = "2 sec cast 2\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (10), Handful of Bismuth Bolts (6), Whimsical Wiring , Gyrating Gear , Safety Switch\nOptional Reagents:\nProfession Trainer:\nKhaz Algar Engineering (25)\nCost:\n125\n\n4UT0-41M3R\nBinds when equipped\nRanged Gun\n1,002 - 1,862 Damage Speed 3.00\n(477.3 damage per second)\n+634 Agility\n+2,323 Stamina\n+ 444 Random Stat 1\n+ 444 Random Stat 2\nDurability 100 / 100\n70\n\"Subtlety is not this gun's specialty.\"" }
entries[447380] = { ["name"] = "Fatal Nightmare", ["text"] = "Instant\nDangerous nightmares lurk in the distant shadows, inflicting lethal damage to those foolish enough stray from the path." }
