entries[447389] = { ["name"] = "Lucky 7 Dice", ["text"] = "Anima Power\n100 yd range\nInstant\nExploding dice appear when you defeat an enemy and bounce between several enemies, dealing severe Physical damage.\n\nThis lasts for 1 min." }
