entries[447392] = { ["name"] = "Supply Bag", ["text"] = "50 yd range\nInstant\nA supply bag has been located!" }
entries[447393] = { ["name"] = "Reno's Random Reactions", ["text"] = "Anima Power\nInstant\nChance when attacking an enemy to throw a random item from Reno's backpack. The item may root, stun, or damage the enemy and enemies around them.\n(Proc chance: 10%, 1m cooldown)" }
entries[447395] = { ["name"] = "Fiery Cleave", ["text"] = "3 sec cast\nThrongus cleaves his enemies with a molten axe, inflicting 12130320 Physical damage to players in front of him." }
entries[447396] = { ["name"] = "Lightning Dust", ["text"] = "40 yd range\nInstant\nYour attacks have a chance to fire a bolt of lightning, dealing (100% of Spell Power) Nature damage to your target." }
entries[447399] = { ["name"] = "Sentinel Swarm", ["text"] = "Unlimited range\nInstant\nThis swarm monitors immediate area, tearing through any who dare try to walk through it. Inflicts 10% of it's target's health as Nature damage on contact every 0.5 sec." }
entries[447400] = { ["name"] = "Infesting Maw", ["text"] = "30 yd range\n2 sec cast\nQueen Rickiticka takes a bit out of her current target inflicting 8 Nature damage, and infesting them with spiders, inflicting an additional 6 every 3 sec. When the infestation expires, Three Hatchlings spring forth from the player." }
