entries[447867] = { ["name"] = "Kah, King of the Deeps", ["text"] = "3.2 sec cast\nWarped by the blood of the Old Gods, its sickly pale skin stretches over its skeletal body. Anglers across Khaz Algar speak of this fish as a messenger of doom, cursing any Angler unfortunate enough to reel it in. Staring into the eyes of this creature will only elaborate its depravity as any reflection is consumed by the abyss." }
