entries[447872] = { ["name"] = "Spongey Scramble", ["text"] = "2 sec cast\nReagents:\nDelver's Waterskin , Fine Egg Powder (10)\nOptional Reagents:\nSecret Ingredient (#318)\nRecipe for 1 servings. Actual number of servings will vary based on cooking skill.\nVendor:\nPolo\nZone:\nCity of Threads\nCost:\n1500\n\nSpongey Scramble\nUse: Restores ( 375000 / 5 * 20) health over 20 sec. Must remain seated while eating.\n\nWell Fed\nIf you spend at least 10 seconds eating you will become Well Fed and gain [source value] of your lowest secondary stat for 15 min.\n68", ["unresolvedValues"] = true }
