entries[447876] = { ["name"] = "Ghoulfish Delight", ["text"] = "2 sec cast\nReagents:\nPrepared Ghoulfish , Simple Stew\nOptional Reagents:\nSecret Ingredient (#318)\nRecipe for 5 servings. Actual number of servings will vary based on cooking skill.\nVendor:\nCaptain Oathmyt\nZone:\nHallowfall\nCost:\n10\n\nGhoulfish Delight\nBinds when picked up\nUse: Restores ( 375000 / 5 * 20) health over 20 sec. Must remain seated while eating.\n\nWell Fed\nIf you spend at least 10 seconds eating, you will become Well Fed and gain 30 Khaz Algar Fishing Skill and 150 Perception for 1 hour.\n75\n\"One angler's worst nightmare is another chef's delicacy\"" }
